local fm = require('fmclient')
vim.api.nvim_create_user_command('FMClient', function() fm.toggle() end, { desc = 'Toggle FM client' })
vim.api.nvim_create_user_command('FMClientSync', function() fm.sync() end, { desc = 'fmclient send_receive' })
vim.api.nvim_create_user_command('FMClientSettings', function() fm.open_screen('settings') end, { desc = 'Open fmclient settings' })
vim.api.nvim_create_user_command('FMClientAdmin', function() fm.open_screen('admin') end, { desc = 'Open fmclient admin section' })
vim.api.nvim_create_user_command('FMClientCompose', function(opts) fm.compose('echo', opts.args) end, { nargs = '*', desc = 'Compose an echo message' })
vim.api.nvim_create_user_command('FMClientNetmail', function(opts) fm.compose('netmail', opts.args) end, { nargs = '?', desc = 'Compose a netmail message' })
vim.api.nvim_create_user_command('FMClientSend', function() fm.send_current_buffer() end, { desc = 'Send current compose buffer' })
vim.api.nvim_create_user_command('FMClientProtocols', function(opts) fm.open_protocols(opts.args ~= '' and opts.args or nil) end, { nargs = '?', desc = 'Open active protocols' })
vim.api.nvim_create_user_command('FMClientToggleProtocols', function() fm.toggle_protocols() end, { desc = 'Toggle protocol messages in the feed' })
local group = vim.api.nvim_create_augroup('FMClient', { clear = true })
vim.api.nvim_create_autocmd('VimEnter', { group = group, callback = function() fm.auto() end, desc = 'Open fmclient when authorized' })
vim.api.nvim_create_autocmd('WinClosed', { group = group, callback = function(args) fm.on_win_closed(tonumber(args.match)) end, desc = 'Keep fmclient panes together' })
